// Category A — a product in an order grid. The whole tile is the press target: pressing it adds the
// product (or opens its options), as on a POS or kiosk ordering grid. ProductCard is a web-shop card with a separate add Button and a fixed 4:3
// image; here the tile is the button and there is no add Button, so it is its own Component, not a
// ProductCard variant. The grid itself is the consumer's Grid (POS: 6 columns, gap 5, side 20).
// When to reach for this rather than ProductCard or a GridList grid: component-usage.md § Product grids.
//
// It renders React Aria's Button itself (Category A). The tile's accessible name is its text in DOM
// order: name, price, then the badge, so it reads "아메리카노 4,500 인기". A photo passed as `media`
// is decorative and takes `alt=""`; the name already names the product.
//
// In edit mode the remove control is a sibling of the tile, never inside it, because a button cannot
// hold a button; it sits inside the tile's own corner so no neighbour covers it, and the badge steps
// aside while editing. ProductTileAdd is the dashed empty position of the same grid.
//
// The owner's colour comes two ways. A palette slot (`zone`, 1 to 8, like TableTile) FILLS the tile, as
// a POS draws a product tile in its owner colour: Sando's categorical
// fills each carry `text.on-color` at the on-colour floor, so the name and price stay measured. Any
// other colour (`swatch`) only marks the inline-start edge, because a fill would put the name on a
// background no contrast check has seen. Either way the name identifies the product, so the colour
// is never the only carrier of meaning.
//
// Sold out depends on the mode. Browsing, a sold-out tile cannot be pressed. In
// edit mode it stays pressable, so the owner can open it to edit; it does not dim there, and the
// sold-out badge alone carries the state.
//
// Paired props: pass both or omit both (`onRemove` with `removeLabel`, `isSoldOut` with
// `soldOutLabel`). The types reject one without the other.
import { Button as AriaButton } from "react-aria-components";
import { Plus, X } from "./icons";
import type { CSSProperties, ReactNode, Ref } from "react";
import { Badge } from "./Badge";
import { Button } from "./Button";
import "./ProductTile.css";

type ProductTileSize = "small" | "medium" | "large";

export interface ProductTileBaseProps {
  /**
   * Size axis: the type rung, the inset and the minimum height.
   *
   * @default "medium"
   */
  size?: ProductTileSize;
  /** The product's name. */
  name: ReactNode;
  /** The price as shown, e.g. "4,500". */
  price?: ReactNode;
  /** A photo above the name: an `<img alt="">`, decorative because the name names the product. Shown square. */
  media?: ReactNode;
  /** A CSS colour the owner picked for the product, drawn as the tile's start edge. */
  swatch?: string;
  /** The owner's colour as a palette slot, 1 to 8: fills the whole tile with on-colour ink. Wins over `swatch`. */
  zone?: 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8;
  /** A badge after the price, e.g. 「인기」 or a stock count. Pass a Badge. */
  badge?: ReactNode;
  /** Called when the tile is pressed. */
  onPress?: () => void;
}

export type ProductTileProps = ProductTileBaseProps &
  (
    | {
        /**
         * When true `soldOutLabel` replaces `badge`. Browsing, the tile cannot be pressed and its text
         * dims; in edit mode (`onRemove` set) it stays pressable and undimmed so it can be opened to edit.
         */
        isSoldOut: boolean;
        /** Visible sold-out label, e.g. "품절". */
        soldOutLabel: string;
      }
    | { isSoldOut?: undefined; soldOutLabel?: undefined }
  ) &
  (
    | {
        /** Edit mode: removes the tile from the grid. */
        onRemove: () => void;
        /** Accessible name of the remove control, e.g. "아메리카노 빼기". */
        removeLabel: string;
      }
    | { onRemove?: undefined; removeLabel?: undefined }
  ) & {
    /** Additional class (optional). sd-product-tile is always preserved. */
    className?: string;
    /** Forwarded to the root element. */
    ref?: Ref<HTMLDivElement>;
  };

export function ProductTile({
  size = "medium",
  name,
  price,
  media,
  swatch,
  zone,
  badge,
  isSoldOut = false,
  soldOutLabel,
  onPress,
  onRemove,
  removeLabel,
  className,
  ref,
}: ProductTileProps) {
  const style = swatch ? ({ "--sd-product-tile-swatch": swatch } as CSSProperties) : undefined;
  const editing = onRemove !== undefined;
  const corner = isSoldOut ? <Badge>{soldOutLabel}</Badge> : editing ? null : badge;
  // Only a tile that cannot be pressed dims: dimmed text is exempt from contrast only while disabled
  // (WCAG 1.4.3), so a sold-out tile in edit mode shows its state by the badge alone.
  const dim = isSoldOut && !editing;
  return (
    <div ref={ref} className={className ? `sd-product-tile ${className}` : "sd-product-tile"}>
      <AriaButton
        className="sd-product-tile__surface"
        data-size={size}
        data-swatch={swatch ? true : undefined}
        data-zone={zone && Number.isInteger(zone) && zone >= 1 && zone <= 8 ? zone : undefined}
        style={style}
        isDisabled={dim}
        onPress={onPress}
      >
        {media != null && (
          <span className="sd-product-tile__media" data-size={size} data-disabled={dim || undefined}>
            {media}
          </span>
        )}
        <span
          className={`sd-product-tile__name sd-type-body-${size}-emphasized`}
          data-disabled={dim || undefined}
        >
          {editing && media == null && <span className="sd-product-tile__remove-spacer" aria-hidden="true" />}
          {name}
        </span>
        {(price != null || corner != null) && (
          <span className="sd-product-tile__footer">
            {price != null && (
              <span
                className={`sd-product-tile__price sd-type-caption-${size}`}
                data-disabled={dim || undefined}
              >
                {price}
              </span>
            )}
            {corner}
          </span>
        )}
      </AriaButton>
      {editing && (
        <Button
          className="sd-product-tile__remove"
          isIconOnly
          variant="secondary"
          size="small"
          aria-label={removeLabel}
          onPress={onRemove}
        >
          <X aria-hidden size="1em" />
        </Button>
      )}
    </div>
  );
}

export interface ProductTileAddProps {
  /**
   * Size axis: matches the tiles beside it.
   *
   * @default "medium"
   */
  size?: ProductTileSize;
  /** Called when the empty position is pressed. */
  onPress?: () => void;
  /** Accessible name, e.g. "상품 추가". */
  "aria-label": string;
  /** Additional class (optional). sd-product-tile-add is always preserved. */
  className?: string;
  /** Forwarded to the button element. */
  ref?: Ref<HTMLButtonElement>;
}

/** An empty position in an editable grid, drawn dashed; pressing it adds a product there. */
export function ProductTileAdd({ size = "medium", onPress, className, ref, ...props }: ProductTileAddProps) {
  return (
    <AriaButton
      {...props}
      ref={ref}
      data-size={size}
      onPress={onPress}
      className={className ? `sd-product-tile-add ${className}` : "sd-product-tile-add"}
    >
      <Plus aria-hidden size="1em" />
    </AriaButton>
  );
}

/* The tile fills the grid cell it is given. A text tile puts the name at the top and the footer (price,
   then any badge) at the bottom of at least the size's minimum height, as on a POS grid; a photo
   tile stacks the square photo, the name and the footer. */
.sd-product-tile {
  position: relative;
  display: grid;
  min-inline-size: 0;
}

.sd-product-tile__surface {
  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: var(--sd-product-tile-gap);
  inline-size: 100%;
  margin: 0;
  border: var(--sd-product-tile-border-width) solid var(--sd-product-tile-border);
  background: var(--sd-product-tile-background);
  color: var(--sd-product-tile-name-foreground);
  /* The price reads its ink through this relay, so a zoned tile can re-ink it without a descendant
     combinator. */
  --sd-product-tile-price-current: var(--sd-product-tile-price-foreground);
  /* The wash each state lays over the tile: the surface wash, or on a zone's solid fill the one named
     for its ink, which goes away from that ink (contrast-contract.mjs § the state layer). */
  --sd-product-tile-state-hover-current: var(--sd-state-hover);
  --sd-product-tile-state-pressed-current: var(--sd-state-pressed);
  text-align: start;
  cursor: pointer;
  outline: none;
  /* Keeps the swatch bar inside the rounded corners. The focus ring is this box's own shadow, so the
     clip does not cut it. */
  overflow: clip;
}

.sd-product-tile__surface[data-size="small"] {
  min-block-size: var(--sd-product-tile-min-height-small);
  padding: var(--sd-product-tile-padding-small);
  border-radius: var(--sd-product-tile-radius-small);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-product-tile__surface[data-size="medium"] {
  min-block-size: var(--sd-product-tile-min-height-medium);
  padding: var(--sd-product-tile-padding-medium);
  border-radius: var(--sd-product-tile-radius-medium);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-product-tile__surface[data-size="large"] {
  min-block-size: var(--sd-product-tile-min-height-large);
  padding: var(--sd-product-tile-padding-large);
  border-radius: var(--sd-product-tile-radius-large);
  corner-shape: superellipse(var(--sd-radius-curve));
}

/* A zone fills the tile from the categorical palette (fill.category.n) with its on-colour ink, the
   edge disappearing into the fill; name and price both take the ink, the price at full strength. */
.sd-product-tile__surface[data-zone="1"] {
  --sd-product-tile-zone-current: var(--sd-product-tile-zone-1);
  --sd-product-tile-zone-ink-current: var(--sd-product-tile-zone-foreground);
}
.sd-product-tile__surface[data-zone="2"] {
  --sd-product-tile-zone-current: var(--sd-product-tile-zone-2);
  --sd-product-tile-zone-ink-current: var(--sd-product-tile-zone-foreground);
}
.sd-product-tile__surface[data-zone="3"] {
  --sd-product-tile-zone-current: var(--sd-product-tile-zone-3);
  --sd-product-tile-zone-ink-current: var(--sd-product-tile-zone-foreground);
}
.sd-product-tile__surface[data-zone="4"] {
  --sd-product-tile-zone-current: var(--sd-product-tile-zone-4);
  --sd-product-tile-zone-ink-current: var(--sd-product-tile-zone-foreground);
}
.sd-product-tile__surface[data-zone="5"] {
  --sd-product-tile-zone-current: var(--sd-product-tile-zone-5);
  --sd-product-tile-zone-ink-current: var(--sd-product-tile-zone-foreground);
}
.sd-product-tile__surface[data-zone="6"] {
  --sd-product-tile-zone-current: var(--sd-product-tile-zone-6);
  --sd-product-tile-zone-ink-current: var(--sd-product-tile-zone-foreground);
}
.sd-product-tile__surface[data-zone="7"] {
  --sd-product-tile-zone-current: var(--sd-product-tile-zone-7);
  --sd-product-tile-zone-ink-current: var(--sd-product-tile-zone-foreground);
}
.sd-product-tile__surface[data-zone="8"] {
  --sd-product-tile-zone-current: var(--sd-product-tile-zone-8);
  --sd-product-tile-zone-ink-current: var(--sd-product-tile-zone-foreground);
}
.sd-product-tile__surface[data-zone] {
  background: var(--sd-product-tile-zone-current, var(--sd-product-tile-background));
  border-color: var(--sd-product-tile-zone-current, var(--sd-product-tile-border));
  color: var(--sd-product-tile-zone-ink-current, var(--sd-product-tile-name-foreground));
  --sd-product-tile-price-current: var(--sd-product-tile-zone-ink-current, var(--sd-product-tile-price-foreground));
  --sd-product-tile-state-hover-current: var(--sd-state-hover-on-color);
  --sd-product-tile-state-pressed-current: var(--sd-state-pressed-on-color);
}

/* The owner's colour as a bar over the start edge: drawn, not a border, so a tile with a swatch keeps
   the same inset as one without. */
/* A zone already fills the tile with the owner's colour, so a swatch beside it is not drawn: one
   owner colour per tile. */
.sd-product-tile__surface[data-swatch]:not([data-zone])::before {
  content: "";
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  inline-size: var(--sd-product-tile-swatch-width);
  border-start-start-radius: inherit;
  corner-start-start-shape: inherit;
  border-end-start-radius: inherit;
  corner-end-start-shape: inherit;
  background: var(--sd-product-tile-swatch);
  pointer-events: none;
}

.sd-product-tile__surface::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
/* Raised to the row's own ink while it is hovered or pressed: this ink is derived at its floor and
   falls under 4.5:1 over the surface wash (contrast-contract.mjs § SURFACE_WASH_INKS). */
.sd-product-tile__surface[data-hovered]:not([data-zone]),
.sd-product-tile__surface[data-pressed]:not([data-zone]) {
  --sd-product-tile-price-current: var(--sd-product-tile-name-foreground);
}
.sd-product-tile__surface[data-hovered]::after {
  background: var(--sd-product-tile-state-hover-current);
}
.sd-product-tile__surface[data-pressed]::after {
  background: var(--sd-product-tile-state-pressed-current);
}
.sd-product-tile__surface[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-product-tile__surface[data-disabled] {
  cursor: not-allowed;
}

.sd-product-tile__media {
  display: block;
  inline-size: 100%;
  aspect-ratio: 1;
  overflow: hidden;
}
.sd-product-tile__media[data-size="small"] {
  border-radius: var(--sd-product-tile-media-radius-small);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-product-tile__media[data-size="medium"] {
  border-radius: var(--sd-product-tile-media-radius-medium);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-product-tile__media[data-size="large"] {
  border-radius: var(--sd-product-tile-media-radius-large);
  corner-shape: superellipse(var(--sd-radius-curve));
}

/* `anywhere` in every mode. Under `:lang(ko)` a spaceless Hangul run is one word, so a name such as
   「아이스아메리카노」 is wider than a POS tile; letting it break keeps all of it visible. The trade,
   accepted: beside the edit-mode spacer a name that would fit on the next line may break mid-word,
   because any overflow-wrap break counts as fitting the narrow first line. Losing content to the clip
   would be worse, and worse again at text zoom (WCAG 1.4.4). */
.sd-product-tile__name {
  overflow-wrap: anywhere;
}

/* The name and price are text the tile draws on its own painted surface, so they take the text inset
   with or without a photo (component-contract.md §6 rule 8, component-owned text). */
.sd-product-tile__name,
.sd-product-tile__price {
  padding-inline: var(--sd-product-tile-text-padding-inline);
}

/* In edit mode on a text tile the remove control sits in the top-end corner. A floated spacer as big
   as the control keeps the name's first line clear of it, and later lines take the full width, so a
   short Korean name on a narrow POS tile still fits whole. */
.sd-product-tile__remove-spacer {
  float: inline-end;
  inline-size: var(--sd-product-tile-remove-reserve);
  block-size: var(--sd-product-tile-remove-reserve);
}

/* A text tile parks the footer at the bottom; a photo tile keeps it under the name. */
.sd-product-tile__footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--sd-product-tile-gap);
  margin-block-start: auto;
}

.sd-product-tile__price {
  color: var(--sd-product-tile-price-current);
  font-variant-numeric: tabular-nums;
}

.sd-product-tile__media[data-disabled],
.sd-product-tile__name[data-disabled],
.sd-product-tile__price[data-disabled] {
  opacity: var(--sd-state-disabled);
}

.sd-product-tile__remove {
  position: absolute;
  inset-block-start: var(--sd-product-tile-remove-inset);
  inset-inline-end: var(--sd-product-tile-remove-inset);
}

.sd-product-tile-add {
  /* The hover and pressed wash is the ::after state layer, under the glyph (component-contract.md § 6). */
  position: relative;
  isolation: isolate;
  display: grid;
  place-items: center;
  inline-size: 100%;
  margin: 0;
  border: var(--sd-product-tile-border-width) dashed var(--sd-product-tile-add-border);
  background: transparent;
  color: var(--sd-product-tile-add-foreground);
  font-size: var(--sd-product-tile-add-icon-size);
  cursor: pointer;
  outline: none;
}
.sd-product-tile-add[data-size="small"] {
  min-block-size: var(--sd-product-tile-min-height-small);
  border-radius: var(--sd-product-tile-radius-small);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-product-tile-add[data-size="medium"] {
  min-block-size: var(--sd-product-tile-min-height-medium);
  border-radius: var(--sd-product-tile-radius-medium);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-product-tile-add[data-size="large"] {
  min-block-size: var(--sd-product-tile-min-height-large);
  border-radius: var(--sd-product-tile-radius-large);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-product-tile-add::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  corner-shape: inherit;
  pointer-events: none;
}
.sd-product-tile-add[data-hovered]::after {
  background: var(--sd-state-hover);
}
.sd-product-tile-add[data-pressed]::after {
  background: var(--sd-state-pressed);
}
.sd-product-tile-add[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
